import React, { useState, useEffect, useRef } from 'react';
import { 
  Send, 
  X, 
  User, 
  Clock, 
  AlertCircle,
  MoreVertical,
  Paperclip,
  Smile,
  Mic,
  Image as ImageIcon,
  FileText,
  MapPin,
  Gift,
  Sparkles,
  Crown,
  Shield,
  CheckCheck,
  Check,
  Pin,
  Star,
  Camera,
  Video,
  Music,
  Headphones,
  Phone,
  Heart,
  ThumbsUp,
  Zap,
  MessageSquare,
  Bot,
  Bell,
  Settings,
  Search,
  Filter,
  Download,
  Copy,
  Forward,
  Reply,
  Bookmark,
  Eye,
  Lock,
  Calendar,
  Battery,
  Wifi,
  Cloud,
  Wind,
  Moon,
  Sun,
  Thermometer,
  Droplets,
  Fire,
  Umbrella,
  Award,
  Trophy,
  Medal,
  Coffee,
  Wine,
  Beer,
  Cocktail,
  Flower2,
  TreePine,
  Leaf,
  Cat,
  Dog,
  Bird,
  Fish,
  Rabbit,
  Butterfly,
  Gamepad2,
  Dice5,
  ChessKing,
  Puzzle,
  Sword,
  Shield as ShieldIcon,
  Castle,
  Compass,
  Globe,
  Navigation,
  Tent,
  Campfire,
  Ship,
  Anchor,
  Plane,
  Car,
  Bike,
  Train,
  Rocket,
  Satellite,
  Atom,
  Cpu,
  Database,
  HardDrive,
  Server,
  Router,
  Smartphone,
  Tablet,
  Monitor,
  Tv,
  Printer,
  Keyboard,
  Mouse,
  Headset,
  Speaker,
  Watch,
  CreditCard,
  Wallet,
  Banknote,
  Coins,
  Gem,
  Diamond,
  Crown as CrownIcon,
  Star as StarIcon,
  Heart as HeartIcon,
  Flag,
  Users,
  UserCircle,
  UserCheck,
  UserX,
  Key,
  Fingerprint,
  QrCode,
  ShieldCheck,
  ShieldAlert,
  LogOut,
  LogIn,
  UserPlus,
  Volume2,
  VolumeX,
  Airplay,
  Cast,
  RotateCw,
  RefreshCw,
  ZoomIn,
  ZoomOut,
  Maximize2,
  Minimize2,
  Edit,
  Trash2,
  Archive,
  EyeOff,
  Unlock,
  Volume1,
  Volume,
  Smartphone as SmartphoneIcon,
  Tablet as TabletIcon,
  Monitor as MonitorIcon,
  Tv as TvIcon,
  Printer as PrinterIcon,
  Keyboard as KeyboardIcon,
  Mouse as MouseIcon,
  Headset as HeadsetIcon,
  Speaker as SpeakerIcon,
  Watch as WatchIcon,
  CreditCard as CreditCardIcon,
  Wallet as WalletIcon,
  Banknote as BanknoteIcon,
  Coins as CoinsIcon,
  Gem as GemIcon,
  Diamond as DiamondIcon,
  CrownIcon as CrownIcon2,
  StarIcon as StarIcon2,
  HeartIcon as HeartIcon2,
  Flag as FlagIcon,
  Users as UsersIcon,
  UserCircle as UserCircleIcon,
  UserCheck as UserCheckIcon,
  UserX as UserXIcon,
  Key as KeyIcon,
  Fingerprint as FingerprintIcon,
  QrCode as QrCodeIcon,
  ShieldCheck as ShieldCheckIcon,
  ShieldAlert as ShieldAlertIcon,
  LogOut as LogOutIcon,
  LogIn as LogInIcon,
  UserPlus as UserPlusIcon,
  Volume2 as Volume2Icon,
  VolumeX as VolumeXIcon,
  Airplay as AirplayIcon,
  Cast as CastIcon,
  RotateCw as RotateCwIcon,
  RefreshCw as RefreshCwIcon,
  ZoomIn as ZoomInIcon,
  ZoomOut as ZoomOutIcon,
  Maximize2 as Maximize2Icon,
  Minimize2 as Minimize2Icon,
  Edit as EditIcon,
  Trash2 as Trash2Icon,
  Archive as ArchiveIcon,
  EyeOff as EyeOffIcon,
  Unlock as UnlockIcon,
  Volume1 as Volume1Icon,
  Volume as VolumeIcon
} from 'lucide-react';

const ChatWindow = ({ 
  conversation, 
  messages, 
  loading, 
  onSendMessage, 
  onClose,
  isAdmin,
  user 
}) => {
  const [inputMessage, setInputMessage] = useState('');
  const [sending, setSending] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showAttachmentMenu, setShowAttachmentMenu] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [pinnedMessages, setPinnedMessages] = useState([]);
  const [showPinned, setShowPinned] = useState(false);
  const [messageReactions, setMessageReactions] = useState({});
  const [hoveredMessage, setHoveredMessage] = useState(null);
  const messagesEndRef = useRef(null);
  const messagesContainerRef = useRef(null);

  const emojis = ['😊', '😂', '🤔', '🎉', '🔥', '❤️', '👍', '👏', '😍', '😎', '🤯', '🥳', '🚀', '💯', '✨'];

  const getOtherUserName = () => {
    if (isAdmin) {
      return `${conversation.user_first_name || ''} ${conversation.user_last_name || ''}`.trim() || 'Utilisateur';
    } else {
      return `${conversation.admin_first_name || ''} ${conversation.admin_last_name || ''}`.trim() || 'Conseiller Premium';
    }
  };

  const getOtherUserEmail = () => {
    if (isAdmin) {
      return conversation.user_email || conversation.email || '';
    }
    return '';
  };

  const getInitials = (name) => {
    if (!name) return '?';
    const names = name.split(' ');
    if (names.length >= 2) {
      return (names[0].charAt(0) + names[1].charAt(0)).toUpperCase();
    }
    return name.charAt(0).toUpperCase();
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'online': return 'bg-emerald-500';
      case 'away': return 'bg-amber-500';
      case 'busy': return 'bg-red-500';
      case 'offline': return 'bg-neutral-500';
      default: return 'bg-emerald-500';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'online': return 'En ligne';
      case 'away': return 'Absent';
      case 'busy': return 'Occupé';
      case 'offline': return 'Hors ligne';
      default: return 'En ligne';
    }
  };

  const handleSend = async () => {
    if (!inputMessage.trim() || sending) return;

    try {
      setSending(true);
      await onSendMessage(conversation.id, inputMessage.trim());
      setInputMessage('');
      setShowEmojiPicker(false);
    } catch (error) {
      console.error('Erreur envoi message:', error);
    } finally {
      setSending(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleEmojiClick = (emoji) => {
    setInputMessage(prev => prev + emoji);
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleScroll = () => {
    if (messagesContainerRef.current) {
      const { scrollTop, scrollHeight, clientHeight } = messagesContainerRef.current;
      setIsTyping(scrollTop < scrollHeight - clientHeight - 100);
    }
  };

  const handleReaction = (messageId, emoji) => {
    setMessageReactions(prev => ({
      ...prev,
      [messageId]: [...(prev[messageId] || []), emoji]
    }));
  };

  const handlePinMessage = (message) => {
    setPinnedMessages(prev => [...prev, message]);
  };

  const formatTime = (dateString) => {
    try {
      const date = new Date(dateString);
      const now = new Date();
      const diffMs = now - date;
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);

      if (diffMins < 1) return 'À l\'instant';
      if (diffMins < 60) return `Il y a ${diffMins} min`;
      if (diffHours < 24) return `Il y a ${diffHours} h`;
      if (diffDays === 1) return 'Hier';
      if (diffDays < 7) return `Il y a ${diffDays} j`;

      return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
    } catch {
      return '--:--';
    }
  };

  const formatFullTime = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleString('fr-FR', {
        weekday: 'long',
        day: 'numeric',
        month: 'long',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch {
      return 'Date inconnue';
    }
  };

  const isMessageRead = (message) => {
    return message.is_read || false;
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    const container = messagesContainerRef.current;
    if (container) {
      container.addEventListener('scroll', handleScroll);
      return () => container.removeEventListener('scroll', handleScroll);
    }
  }, []);

  const attachmentOptions = [
    { icon: ImageIcon, label: 'Photo', color: 'text-emerald-500' },
    { icon: Video, label: 'Vidéo', color: 'text-purple-500' },
    { icon: FileText, label: 'Document', color: 'text-blue-500' },
    { icon: Music, label: 'Audio', color: 'text-pink-500' },
    { icon: MapPin, label: 'Localisation', color: 'text-red-500' },
    { icon: Camera, label: 'Appareil photo', color: 'text-amber-500' },
  ];

  const messageActions = [
    { icon: Reply, label: 'Répondre', color: 'text-blue-500' },
    { icon: Copy, label: 'Copier', color: 'text-neutral-500' },
    { icon: Forward, label: 'Transférer', color: 'text-purple-500' },
    { icon: Bookmark, label: 'Enregistrer', color: 'text-amber-500' },
    { icon: Pin, label: 'Épingler', color: 'text-emerald-500' },
    { icon: Edit, label: 'Modifier', color: 'text-sky-500' },
    { icon: Trash2, label: 'Supprimer', color: 'text-red-500' },
  ];

  const quickReactions = ['❤️', '👍', '😂', '😮', '😢', '🎉'];

  return (
    <div className="relative h-[600px] flex flex-col bg-gradient-to-br from-white via-white to-white/95 dark:from-neutral-900 dark:via-neutral-900 dark:to-neutral-900/95 rounded-2xl shadow-2xl shadow-primary-500/10 border border-white/20 dark:border-neutral-800/50 overflow-hidden backdrop-blur-sm">

      {/* Effet de fond animé */}
      <div className="absolute inset-0 bg-gradient-to-br from-primary-500/5 via-transparent to-secondary-500/5 animate-gradient"></div>

      {/* Header avec glassmorphism */}
      <div className="relative z-10 flex-shrink-0 p-4 bg-gradient-to-r from-white/80 to-white/60 dark:from-neutral-900/80 dark:to-neutral-800/60 border-b border-white/20 dark:border-neutral-800/50 backdrop-blur-md">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="relative">
              <div className="h-12 w-12 rounded-xl bg-gradient-to-br from-primary-500 via-primary-600 to-secondary-600 flex items-center justify-center shadow-lg shadow-primary-500/20">
                <span className="text-white font-bold text-lg">{getInitials(getOtherUserName())}</span>
              </div>
              <div className={`absolute -bottom-1 -right-1 h-4 w-4 rounded-full ${getStatusColor('online')} border-2 border-white dark:border-neutral-900`}></div>

              {/* Badge admin ou premium */}
              {isAdmin ? (
                <div className="absolute -top-1 -left-1">
                  <Shield className="w-4 h-4 text-emerald-500 fill-emerald-500" />
                </div>
              ) : conversation.user_is_premium && (
                <div className="absolute -top-1 -left-1">
                  <Crown className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                </div>
              )}
            </div>

            <div className="flex-1">
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-lg text-neutral-900 dark:text-white">
                  {getOtherUserName()}
                </h3>

                {/* Badges */}
                {conversation.status !== 'open' && (
                  <span className={`px-2 py-0.5 text-xs font-bold ${getStatusColor(conversation.status)}/20 text-${getStatusColor(conversation.status).split('-')[1]}-600 dark:text-${getStatusColor(conversation.status).split('-')[1]}-400 rounded`}>
                    {getStatusText(conversation.status)}
                  </span>
                )}

                {conversation.is_urgent && (
                  <span className="px-2 py-0.5 text-xs font-bold bg-red-500/10 text-red-600 dark:text-red-400 rounded flex items-center gap-1">
                    <Zap className="w-3 h-3" />
                    Urgent
                  </span>
                )}
              </div>

              <div className="flex items-center gap-2 mt-0.5">
                <div className="flex items-center gap-1">
                  <div className={`h-2 w-2 rounded-full ${getStatusColor('online')} animate-pulse`}></div>
                  <span className="text-xs text-neutral-500 dark:text-neutral-400">
                    {getStatusText('online')}
                  </span>
                </div>

                {getOtherUserEmail() && (
                  <>
                    <span className="text-neutral-300 dark:text-neutral-700">•</span>
                    <span className="text-xs text-neutral-500 dark:text-neutral-400 truncate max-w-[150px]">
                      {getOtherUserEmail()}
                    </span>
                  </>
                )}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-1">
            {/* Actions header */}
            <button className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-all group relative">
              <Bell className="w-5 h-5 text-neutral-500 group-hover:text-primary-500" />
              <span className="absolute -top-1 -right-1 h-2 w-2 bg-red-500 rounded-full"></span>
            </button>

            <button className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-all group">
              <Search className="w-5 h-5 text-neutral-500 group-hover:text-primary-500" />
            </button>

            <button className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-all group">
              <Users className="w-5 h-5 text-neutral-500 group-hover:text-primary-500" />
            </button>

            <button 
              onClick={onClose}
              className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-all group md:hidden"
            >
              <X className="w-5 h-5 text-neutral-500 group-hover:text-primary-500" />
            </button>
          </div>
        </div>
      </div>

      {/* Messages avec effet de profondeur */}
      <div 
        ref={messagesContainerRef}
        className="relative z-10 flex-1 overflow-y-auto p-4"
      >
        {loading ? (
          <div className="flex flex-col items-center justify-center h-full">
            <div className="relative">
              <div className="animate-spin rounded-full h-12 w-12 border-3 border-primary-500/30 border-t-primary-500"></div>
              <Sparkles className="absolute inset-0 m-auto w-6 h-6 text-primary-500 animate-pulse" />
            </div>
            <p className="text-neutral-500 mt-3">Chargement des messages...</p>
          </div>
        ) : messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8">
            <div className="h-24 w-24 rounded-2xl bg-gradient-to-br from-primary-500/10 to-secondary-500/10 flex items-center justify-center mx-auto mb-4">
              <MessageSquare className="h-12 w-12 text-primary-500/50" />
            </div>
            <h3 className="text-xl font-semibold text-neutral-900 dark:text-white mb-2">
              Commencez la conversation
            </h3>
            <p className="text-sm text-neutral-500 dark:text-neutral-400 max-w-md mx-auto">
              {isAdmin 
                ? 'Envoyez votre premier message à cet utilisateur pour commencer l\'assistance'
                : 'Envoyez votre premier message à notre équipe de support'
              }
            </p>
            <div className="mt-6 flex flex-wrap gap-2 justify-center">
              <button className="px-4 py-2 bg-primary-500/10 border border-primary-500/20 rounded-lg text-sm text-primary-600 dark:text-primary-400">
                Comment puis-je vous aider ?
              </button>
              <button className="px-4 py-2 bg-primary-500/10 border border-primary-500/20 rounded-lg text-sm text-primary-600 dark:text-primary-400">
                Besoin d'informations
              </button>
              <button className="px-4 py-2 bg-primary-500/10 border border-primary-500/20 rounded-lg text-sm text-primary-600 dark:text-primary-400">
                Support technique
              </button>
            </div>
          </div>
        ) : (
          <>
            {/* Messages épinglés */}
            {pinnedMessages.length > 0 && (
              <div className="mb-4">
                <button
                  onClick={() => setShowPinned(!showPinned)}
                  className="w-full p-3 bg-gradient-to-r from-amber-500/10 to-amber-500/5 border border-amber-500/20 rounded-xl flex items-center justify-between hover:bg-amber-500/15 transition-colors"
                >
                  <div className="flex items-center gap-2">
                    <Pin className="w-4 h-4 text-amber-500" />
                    <span className="text-sm font-medium text-amber-600 dark:text-amber-400">
                      {pinnedMessages.length} message{pinnedMessages.length > 1 ? 's' : ''} épinglé{pinnedMessages.length > 1 ? 's' : ''}
                    </span>
                  </div>
                  <ChevronDown className={`w-4 h-4 text-amber-500 transform transition-transform ${showPinned ? 'rotate-180' : ''}`} />
                </button>

                {showPinned && (
                  <div className="mt-2 space-y-2">
                    {pinnedMessages.map((msg, index) => (
                      <div key={index} className="p-3 bg-amber-500/5 border border-amber-500/10 rounded-lg">
                        <p className="text-sm text-neutral-900 dark:text-white">{msg.content}</p>
                        <div className="flex items-center justify-between mt-2">
                          <span className="text-xs text-amber-600 dark:text-amber-400">
                            {formatTime(msg.created_at)}
                          </span>
                          <button
                            onClick={() => setPinnedMessages(prev => prev.filter((_, i) => i !== index))}
                            className="text-xs text-amber-600 dark:text-amber-400 hover:text-amber-700"
                          >
                            Désépingler
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Séparateur de date */}
            <div className="flex items-center justify-center my-6">
              <div className="h-px flex-1 bg-gradient-to-r from-transparent via-neutral-300/50 dark:via-neutral-700/50 to-transparent"></div>
              <span className="px-3 py-1 text-xs font-medium bg-white/50 dark:bg-neutral-800/50 text-neutral-500 rounded-full">
                {new Date().toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' })}
              </span>
              <div className="h-px flex-1 bg-gradient-to-r from-transparent via-neutral-300/50 dark:via-neutral-700/50 to-transparent"></div>
            </div>

            {/* Messages */}
            <div className="space-y-4">
              {messages.map((message) => {
                const isCurrentUser = message.sender_id === user.id;
                const reactions = messageReactions[message.id] || [];
                const isHovered = hoveredMessage === message.id;

                return (
                  <div
                    key={message.id}
                    onMouseEnter={() => setHoveredMessage(message.id)}
                    onMouseLeave={() => setHoveredMessage(null)}
                    className={`relative group ${isCurrentUser ? 'ml-auto' : 'mr-auto'} max-w-[85%]`}
                  >
                    {/* Effet de fond au survol */}
                    {isHovered && (
                      <div className="absolute inset-0 bg-gradient-to-r from-primary-500/5 to-secondary-500/5 rounded-2xl blur opacity-50 transform scale-105"></div>
                    )}

                    <div className="relative">
                      {/* Nom de l'expéditeur pour les messages reçus */}
                      {!isCurrentUser && (
                        <div className="flex items-center gap-2 mb-1 ml-2">
                          <span className="text-xs font-medium text-neutral-600 dark:text-neutral-400">
                            {message.sender_first_name || getOtherUserName()}
                          </span>
                          {message.sender_is_admin && (
                            <Shield className="w-3 h-3 text-emerald-500" />
                          )}
                        </div>
                      )}

                      {/* Message */}
                      <div className={`relative rounded-2xl p-4 transition-all duration-300 ${
                        isCurrentUser
                          ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg shadow-primary-500/25 rounded-br-none'
                          : 'bg-white/60 dark:bg-neutral-800/60 text-neutral-900 dark:text-white shadow-lg rounded-bl-none border border-white/20 dark:border-neutral-700/30'
                      }`}>
                        <p className="text-sm leading-relaxed">{message.content}</p>

                        {/* Infos du message */}
                        <div className={`flex items-center justify-between mt-3 ${
                          isCurrentUser ? 'text-white/80' : 'text-neutral-500'
                        }`}>
                          <div className="flex items-center gap-2">
                            <Clock className="w-3 h-3" />
                            <span className="text-xs">{formatTime(message.created_at)}</span>

                            {/* Indicateur de lecture */}
                            {isCurrentUser && isMessageRead(message) && (
                              <div className="flex items-center gap-0.5">
                                <CheckCheck className="w-3 h-3" />
                                <CheckCheck className="w-3 h-3 -ml-1.5" />
                              </div>
                            )}
                          </div>

                          {/* Actions du message (apparaissent au survol) */}
                          {isHovered && (
                            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              {messageActions.map((action, index) => (
                                <button
                                  key={index}
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    if (action.label === 'Épingler') handlePinMessage(message);
                                  }}
                                  className="p-1 hover:bg-white/10 dark:hover:bg-white/5 rounded"
                                >
                                  <action.icon className={`w-3 h-3 ${action.color}`} />
                                </button>
                              ))}
                            </div>
                          )}
                        </div>

                        {/* Réactions */}
                        {reactions.length > 0 && (
                          <div className="flex flex-wrap gap-1 mt-2">
                            {reactions.map((emoji, index) => (
                              <span
                                key={index}
                                className="px-2 py-1 bg-white/20 dark:bg-neutral-700/50 rounded-lg text-xs"
                              >
                                {emoji}
                              </span>
                            ))}
                          </div>
                        )}

                        {/* Boutons de réaction rapide (apparaissent au survol) */}
                        {isHovered && (
                          <div className="absolute -bottom-2 right-2 flex items-center gap-1 bg-white dark:bg-neutral-800 rounded-full px-2 py-1 shadow-lg border border-white/20 dark:border-neutral-700/50 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                            {quickReactions.map((emoji, index) => (
                              <button
                                key={index}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleReaction(message.id, emoji);
                                }}
                                className="p-1 hover:scale-125 transition-transform"
                              >
                                <span className="text-sm">{emoji}</span>
                              </button>
                            ))}
                          </div>
                        )}
                      </div>

                      {/* Heure complète au clic */}
                      <div className="mt-1 text-xs text-neutral-500 text-center opacity-0 group-hover:opacity-100 transition-opacity">
                        {formatFullTime(message.created_at)}
                      </div>
                    </div>
                  </div>
                );
              })}

              {/* Indicateur de frappe */}
              {isTyping && (
                <div className="flex items-center gap-2 p-3 bg-gradient-to-r from-primary-500/10 to-secondary-500/10 border border-primary-500/20 rounded-xl">
                  <div className="flex items-center gap-1">
                    <div className="h-2 w-2 bg-primary-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                    <div className="h-2 w-2 bg-primary-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                    <div className="h-2 w-2 bg-primary-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                  </div>
                  <span className="text-sm text-primary-600 dark:text-primary-400">
                    {getOtherUserName()} est en train d'écrire...
                  </span>
                </div>
              )}

              <div ref={messagesEndRef} />
            </div>
          </>
        )}
      </div>

      {/* Input avec effets avancés */}
      <div className="relative z-10 flex-shrink-0 p-4 border-t border-white/20 dark:border-neutral-800/50 bg-white/30 dark:bg-neutral-900/30 backdrop-blur-sm">
        {/* Menu des pièces jointes */}
        {showAttachmentMenu && (
          <div className="absolute bottom-full left-0 right-0 mb-2 p-3 bg-white dark:bg-neutral-800 rounded-xl shadow-2xl border border-white/20 dark:border-neutral-700/50 backdrop-blur-sm">
            <div className="grid grid-cols-3 gap-2">
              {attachmentOptions.map((option, index) => (
                <button
                  key={index}
                  className="flex flex-col items-center justify-center p-3 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors"
                  onClick={() => setShowAttachmentMenu(false)}
                >
                  <option.icon className={`w-6 h-6 ${option.color} mb-2`} />
                  <span className="text-xs text-neutral-600 dark:text-neutral-400">{option.label}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Picker d'emoji */}
        {showEmojiPicker && (
          <div className="absolute bottom-full left-0 right-0 mb-2 p-3 bg-white dark:bg-neutral-800 rounded-xl shadow-2xl border border-white/20 dark:border-neutral-700/50 backdrop-blur-sm">
            <div className="flex flex-wrap gap-2">
              {emojis.map((emoji, index) => (
                <button
                  key={index}
                  onClick={() => handleEmojiClick(emoji)}
                  className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors text-lg hover:scale-125 transition-transform"
                >
                  {emoji}
                </button>
              ))}
            </div>
          </div>
        )}

        <div className="flex items-center gap-2">
          {/* Boutons d'actions */}
          <div className="flex items-center gap-1">
            <button
              onClick={() => setShowAttachmentMenu(!showAttachmentMenu)}
              className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-colors group relative"
            >
              <Paperclip className="w-5 h-5 text-neutral-500 group-hover:text-primary-500" />
            </button>

            <button
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-colors group"
            >
              <Smile className="w-5 h-5 text-neutral-500 group-hover:text-primary-500" />
            </button>

            <button className="p-2 hover:bg-white/20 dark:hover:bg-white/10 rounded-lg transition-colors group">
              <Mic className="w-5 h-5 text-neutral-500 group-hover:text-primary-500" />
            </button>
          </div>

          {/* Champ de saisie */}
          <div className="flex-1 relative">
            <div className="absolute inset-0 bg-gradient-to-r from-primary-500/10 to-secondary-500/10 rounded-xl blur opacity-0 group-hover:opacity-100 transition-opacity"></div>
            <div className="relative">
              <input
                type="text"
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                placeholder={`Écrivez à ${getOtherUserName()}...`}
                className="w-full px-4 py-3 bg-white/50 dark:bg-neutral-800/50 border border-white/30 dark:border-neutral-700/50 rounded-xl text-sm text-neutral-900 dark:text-white placeholder-neutral-400 dark:placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-transparent backdrop-blur-sm transition-all duration-200"
                disabled={sending}
              />
            </div>
          </div>

          {/* Bouton d'envoi avec effets spéciaux */}
          <button
            onClick={handleSend}
            disabled={!inputMessage.trim() || sending}
            className={`p-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg shadow-primary-500/25 hover:shadow-primary-500/40 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 relative overflow-hidden group ${
              inputMessage.trim() ? 'scale-105' : ''
            }`}
          >
            {/* Effet de brillance */}
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000"></div>

            {sending ? (
              <div className="relative">
                <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                <Sparkles className="absolute inset-0 m-auto w-3 h-3 text-white animate-pulse" />
              </div>
            ) : (
              <Send className="w-5 h-5 transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
            )}

            {/* Tooltip */}
            <div className="absolute bottom-full right-0 mb-2 px-3 py-1 bg-neutral-900 text-white text-xs rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
              Envoyer le message
            </div>
          </button>
        </div>

        {/* Indicateur de caractères */}
        <div className="flex items-center justify-between mt-2 px-2">
          <div className="flex items-center gap-2 text-xs text-neutral-500">
            <span>Appuyez sur Entrée pour envoyer</span>
            <span className="text-neutral-300 dark:text-neutral-700">•</span>
            <span>Shift + Entrée pour un saut de ligne</span>
          </div>
          <div className={`text-xs ${
            inputMessage.length > 200 ? 'text-red-500' : 'text-neutral-500'
          }`}>
            {inputMessage.length}/500
          </div>
        </div>
      </div>

      {/* Bouton scroll vers le bas */}
      {isTyping && (
        <button
          onClick={scrollToBottom}
          className="absolute bottom-20 right-4 p-2 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-full shadow-lg z-20 hover:scale-110 transition-transform"
        >
          <ChevronDown className="w-5 h-5" />
        </button>
      )}
    </div>
  );
};

// Composant ChevronDown manquant
const ChevronDown = ({ className }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
  </svg>
);

export default ChatWindow;
